mapper.sql:
WHERE (#{scopeType} IS NULL OR detail.scope_type = #{scopeType})
  AND (#{scopeId} IS NULL OR detail.scope_id = #{scopeId})

  AND task.operation IN

      #{operation}



  AND task.status IN

      #{status}



  AND COALESCE(task.completed_at, task.started_at, task.queued_at, task.created_at) >= #{timeFrom}


  AND COALESCE(task.completed_at, task.started_at, task.queued_at, task.created_at) <= #{timeTo}


  AND (
      lower(task.id) LIKE '%' || #{keyword} || '%'
      OR lower(COALESCE(detail.scope_id, '')) LIKE '%' || #{keyword} || '%'
      OR lower(COALESCE(task.current_item, '')) LIKE '%' || #{keyword} || '%'
      OR lower(COALESCE(task.error_message, '')) LIKE '%' || #{keyword} || '%'
      OR lower(COALESCE(folder.display_name, '')) LIKE '%' || #{keyword} || '%'
      OR lower(COALESCE(folder.folder_path, '')) LIKE '%' || #{keyword} || '%'
  )

mapper.insert:
INSERT INTO knowledge_folder_runs (
    id, scope_type, scope_id, scanned_count, parsed_count, skipped_count, failed_count,
    indexed_document_count, indexed_chunk_count, failed_document_count,
    failures_json, error_stage, error_detail
) VALUES (
    #{id}, #{scopeType}, #{scopeId}, #{scannedCount}, #{parsedCount}, #{skippedCount}, #{failedCount},
    #{indexedDocumentCount}, #{indexedChunkCount}, #{failedDocumentCount},
    #{failuresJson}, #{errorStage}, #{errorDetail}
)

mapper.select:
SELECT
LEFT JOIN knowledge_folders folder ON detail.scope_type = 'KNOWLEDGE_FOLDER' AND folder.id = detail.scope_id
ORDER BY task.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE knowledge_folder_runs
SET error_stage = #{errorStage},
    error_detail = #{errorDetail}
WHERE id = #{id}
